/**
 * Helper to fetch the value of the first matching header in a IHeaderBlock,
 * or null if none.
 */
function getHeader(headerBlock, name) {
  for (let i = 0; i < headerBlock.numHeaders; ++i) {
    if (name == headerBlock.name(i)) {
      return headerBlock.value(i);
    }
  }
  return null;
}
